```javascript
import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-thumb';
  group.position.set(-1.25, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const ink = 0x16161d;
  const paper = 0xe8ecf2;
  const accent = 0xff2a38;
  const surface = 0x0b0b10;

  // Backing card plate (machined-metal PBR)
  const cardMat = new THREE.MeshPhysicalNodeMaterial();
  cardMat.colorNode = color(ink);
  cardMat.metalness = 0.5;
  cardMat.roughness = 0.55;
  cardMat.clearcoat = 0.2;
  cardMat.clearcoatRoughness = 0.4;
  const cardGeo = new THREE.PlaneGeometry(1.6, 1.0);
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.z = -0.02;
  group.add(cardMesh);

  // Caption strip
  const stripMat = new THREE.MeshStandardNodeMaterial();
  stripMat.colorNode = color(surface);
  stripMat.metalness = 0.4;
  stripMat.roughness = 0.6;
  const stripGeo = new THREE.PlaneGeometry(1.6, 0.22);
  const stripMesh = new THREE.Mesh(stripGeo, stripMat);
  stripMesh.position.set(0, -0.39, 0.001);
  group.add(stripMesh);

  // Accent rim light strip
  const rimMat = new THREE.MeshBasicNodeMaterial();
  rimMat.colorNode = color(accent);
  const rimGeo = new THREE.PlaneGeometry(1.62, 0.02);
  const rimMesh = new THREE.Mesh(rimGeo, rimMat);
  rimMesh.position.set(0, -0.28, 0.002);
  group.add(rimMesh);

  // Mesh slot for GLB
  const meshSlot = new THREE.Group();
  meshSlot.position.set(0, 0.08, 0.05);
  meshSlot.scale.set(0.5, 0.5, 0.5);
  group.add(meshSlot);

  let loadedGlb = null;
  try {
    const gltf = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb');
    if (gltf && gltf.scene) {
      loadedGlb = gltf.scene;
      meshSlot.add(loadedGlb);
    }
  } catch (e) {
    // fail silently, keep card usable without mesh
  }

  // Apply cinematic primitives
  ctx.primitives['parallax-scroll'](group, { trigger: 'scroll', intensity: 0.4 });
  ctx.primitives['magnetic-cursor'](group, { trigger: 'hover', radius: 1.2, strength: 0.35 });

  // Interaction state
  const baseY = group.position.y;
  let hoverTl = null;
  let settleTl = null;

  const onHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    if (ctx.eventBus && typeof ctx.eventBus.emit === 'function') {
      ctx.eventBus.emit('hub-features.select', { id: 'hub-features-card-0' });
    } else if (typeof ctx.emit === 'function') {
      ctx.emit('hub-features.select', { id: 'hub-features-card-0' });
    }
    gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });
  };

  // Weighted-settle entrance
  group.scale.set(0.001, 0.001, 0.001);
  settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.6,
    ease: 'power4.out',
  }).to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.3,
    ease: 'power4.out',
  });

  group.userData.handlers = {
    hover: onHoverIn,
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (settleTl) settleTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    cardGeo.dispose();
    cardMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    rimGeo.dispose();
    rimMat.dispose();

    if (loadedGlb) {
      loadedGlb.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
